47:TClear () - Clears TILE Delay Link List
48: *-------------------------------------------------------------------------*/
49:PRIVATE VOID
50:TClear (
51:VOID
52:)
53:{
54:   INT loop;
55:  
56:   first_delay.prev = NUL;
57:   first_delay.next = &last_delay;
58:  
59:   last_delay.prev = &first_delay;
60:   last_delay.next = NUL;
61:  
62:   free_delay = tdel;
63:  
64:   memset ( tdel, 0, sizeof ( tdel ) );
65:  
66:   for ( loop = 0; loop < MAX_TILEDELAY-1; loop++ )
67:      tdel[ loop ].next = &tdel [ loop + 1 ];
68:}
