162:)
163:{
164:   BOOL flag = FALSE;
165:  
166:   if ( y + 32 <= 0 ) return;
167:   if ( y >= SCREENHEIGHT ) return;
168:  
169:   tileloopy   = 32;
170:   tilepic     = inpic;
171:  
172:   if ( y < 0 )
173:   {
174:      tilepic += FMUL32 ( -y );
175:      tileloopy += y;
176:      y = 0;
177:      flag = TRUE;
178:   }
179:  
180:   if ( y + tileloopy > SCREENHEIGHT )
181:   {
182:      tileloopy = SCREENHEIGHT - y;
183:      flag = TRUE;
184:   }
185:  
186:   tilestart = displaybuffer + x + ylookup [ y ];
187:  
188:   if ( flag )
189:      TILE_ClipDraw();
190:   else
191:      TILE_Draw();
192:}
