{
   TILEDELAY * td;
  
   if ( ts->mapspot == EMPTY || ts->mapspot < tilepos ) return;

   if ( delay )
   {
      td = TGet();
      if ( td )
      {
         td->ts = ts;
         td->mapspot = ts->mapspot;
         td->frames = delay;
         td->item  = eitems [ ts->mapspot ];
      }
      eitems [ ts->mapspot ]  =  titems [ ts->mapspot ];
   }
   else
   {
      ts->item  = eitems [ ts->mapspot ];
       titems [ ts->mapspot ] = eitems [ ts->mapspot ];
   }
}

